SELECT COUNT(*)
FROM sys_user
WHERE username = #{username}

    AND user_id != #{excludeUserId}

SELECT COUNT(*)
FROM sys_user
WHERE phone = #{phone}
  AND is_deleted = 0

    AND user_id != #{excludeUserId}

SELECT COUNT(*)
FROM sys_user
WHERE email = #{email}
  AND is_deleted = 0

    AND user_id != #{excludeUserId}

mapper.update:
UPDATE sys_user
SET is_deleted = 1,
    update_by = #{updateBy},
    update_time = #{updateTime}
WHERE user_id = #{userId}
  AND is_deleted = 0
